): Promise<readonly IssueLabel[]> {

/**
 * Points every issue assignment of `sourceLabelId` at `targetLabelId`, then
 * deletes the source label. Issues that already carry the target keep a single
 * row: the unique `(issue_id, label_id)` index would reject an update onto a
 * label the issue already has, so those source rows are removed first.
 * Returns how many issues carried the source beforehand.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  if (sourceLabelId === targetLabelId) {
    throw new Error("Cannot merge a label into itself");
  }

  const db = getDb();
  return db.transaction((tx) => {
    const source = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .get();
    const target = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, targetLabelId)))
      .get();
    if (!source || !target) {
      throw new Error(
        `Label ${!source ? sourceLabelId : targetLabelId} not found`,
      );
    }

    const carryingSource = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    const sourceIssueIds = [
      ...new Set(carryingSource.map((row) => row.issueId)),
    ];

    if (sourceIssueIds.length > 0) {
      const alreadyOnTarget = tx
        .select({ issueId: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, targetLabelId),
            inArray(issueLabels.issueId, sourceIssueIds),
          ),
        )
        .all();

      const overlap = [...new Set(alreadyOnTarget.map((row) => row.issueId))];
      if (overlap.length > 0) {
        tx.delete(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, orgId),
              eq(issueLabels.labelId, sourceLabelId),
              inArray(issueLabels.issueId, overlap),
            ),
          )
          .run();
      }

      tx.update(issueLabels)
        .set({ labelId: targetLabelId })
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
          ),
        )
        .run();
    }

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return sourceIssueIds.length;
  });
}

