import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { mergeLabelsSchema } from "@/schemas/label";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { NotFoundError } from "@/server/services/_support";
import { mergeLabels } from "@/server/services/label-service";
import type { LabelId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const SOURCE = "01ARZ3NDEKTSV4RRFFQ69G5FAV";
const TARGET = "01ARZ3NDEKTSV4RRFFQ69G5FAW";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function makeLabel(tenant: Tenant, name: string, color = "#112233") {
  return labelRepo.insertLabel({
    orgId: tenant.org.id,
    name,
    color,
    description: `${name} desc`,
  });
}

async function makeIssue(
  tenant: Tenant,
  title: string,
  labelIds: readonly LabelId[],
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    { ...issueInput(tenant.org.id, tenant.project.id, { title }), labelIds: [...labelIds] },
    tenant.userIds.owner,
    number,
  );
}

async function labelIdsOf(tenant: Tenant, issueId: string) {
  const grouped = await labelRepo.listLabelsForIssues(tenant.org.id, [issueId as never]);
  return (grouped[issueId] ?? []).map((label) => label.id).sort();
}

describe("mergeLabels", () => {
  it("rejects a schema where source and target are the same id", () => {
    const orgId = "01ARZ3NDEKTSV4RRFFQ69G5FAX";
    const parsed = mergeLabelsSchema.safeParse({
      orgId,
      sourceLabelId: SOURCE,
      targetLabelId: SOURCE,
    });
    expect(parsed.success).toBe(false);

    const ok = mergeLabelsSchema.safeParse({
      orgId,
      sourceLabelId: SOURCE,
      targetLabelId: TARGET,
    });
    expect(ok.success).toBe(true);
  });

  it("retargets issues, including archived and already-both, then deletes the source", async () => {
    const tenant = await createTenant("merge-happy");
    const source = await makeLabel(tenant, "defect", "#aa0000");
    const target = await makeLabel(tenant, "bug", "#00aa00");
    const other = await makeLabel(tenant, "chore", "#0000aa");

    const onlySource = await makeIssue(tenant, "only source", [source.id]);
    const both = await makeIssue(tenant, "both", [source.id, target.id]);
    const onlyTarget = await makeIssue(tenant, "only target", [target.id]);
    const untouched = await makeIssue(tenant, "untouched", [other.id]);
    const archived = await makeIssue(tenant, "archived", [source.id, other.id]);
    await issueRepo.archiveIssue(tenant.org.id, archived.id);

    const result = await mergeLabels(tenant.actors.admin, {
      orgId: tenant.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });

    expect(result.issuesRelabelled).toBe(3);
    expect(result.label).toEqual(target);
    expect(await labelRepo.findLabelById(tenant.org.id, source.id)).toBeNull();
    expect(await labelRepo.findLabelById(tenant.org.id, target.id)).toEqual(target);
    expect(await labelIdsOf(tenant, onlySource.id)).toEqual([target.id].sort());
    expect(await labelIdsOf(tenant, both.id)).toEqual([target.id].sort());
